-- ----------------------------
-- Table structure for h_article
-- ----------------------------
DROP TABLE IF EXISTS `h_article`;
CREATE TABLE `h_article` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `content` text COMMENT '内容',
  `title` varchar(255) NOT NULL DEFAULT '' COMMENT '标题',
  `create_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '1：启用 -1:禁用',
  `thumb` varchar(255) NOT NULL DEFAULT '' COMMENT '缩略图',
  `sort` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '排序',
  `desc` varchar(255) NOT NULL DEFAULT '' COMMENT '描述',
  `create_operator` varchar(31) NOT NULL DEFAULT '' COMMENT '创建人账户',
  `update_operator` varchar(31) NOT NULL DEFAULT '' COMMENT '更新人账户',
  `read_count` int(11) unsigned NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=26 DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;

