  `url` varchar(500) DEFAULT '' COMMENT '访问链接',
  `mime` varchar(100) DEFAULT '' COMMENT '文件类型',
  `size` bigint(20) DEFAULT '0' COMMENT '文件大小',
  `uid` bigint(20) NOT NULL DEFAULT '0' COMMENT '会员编号',
