  `order_sn` varchar(255) NOT NULL DEFAULT '' COMMENT '流水号',
  `before_frozen_amount` decimal(12,3) NOT NULL DEFAULT '0.000' COMMENT '变动前冻结金额',
  `after_froze_amount` decimal(12,3) NOT NULL DEFAULT '0.000' COMMENT '冻结后冻结金额',
  PRIMARY KEY (`id`) USING BTREE
