-- ----------------------------
-- Table structure for h_game_play_card
-- ----------------------------
DROP TABLE IF EXISTS `h_game_play_card`;
CREATE TABLE `h_game_play_card` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `game_round_id` int(11) unsigned NOT NULL COMMENT '关联游戏局ID',
  `seq` smallint(5) unsigned NOT NULL DEFAULT '0' COMMENT '本局出牌顺序(从1递增)',
  `member_id` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '出牌用户ID',
  `now_cards` varchar(255) NOT NULL COMMENT '剩余牌',
  `cards` varchar(255) NOT NULL DEFAULT '' COMMENT '出的牌',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '出牌时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_game_round_id` (`game_round_id`) USING BTREE COMMENT '局ID索引',
  KEY `idx_user_id` (`member_id`) USING BTREE COMMENT '用户ID索引'
) ENGINE=InnoDB AUTO_INCREMENT=13931 DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='出牌记录表';

