-- ----------------------------
-- Table structure for h_game_record
-- ----------------------------
DROP TABLE IF EXISTS `h_game_record`;
CREATE TABLE `h_game_record` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT COMMENT '录像ID(对外 recordId)',
  `schema_ver` tinyint(3) unsigned NOT NULL DEFAULT '1' COMMENT 'JSON 协议版本，便于以后升级',
  `game_type` tinyint(3) unsigned NOT NULL COMMENT '1斗地主 2斗牛 3金花 4跑得快 5癞子 7红中',
  `room_id` int(10) unsigned NOT NULL DEFAULT '0' COMMENT 'h_game_room.id',
  `round_id` int(10) unsigned NOT NULL DEFAULT '0' COMMENT 'h_game_round.id',
  `room_num` varchar(32) NOT NULL DEFAULT '' COMMENT '房间号(展示/检索)',
  `owner_id` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '房主 member_id',
  `cur_round` smallint(5) unsigned NOT NULL DEFAULT '1' COMMENT '房间内第几局',
  `max_round` smallint(5) unsigned NOT NULL DEFAULT '1' COMMENT '房间总局数',
  `player_num` tinyint(3) unsigned NOT NULL DEFAULT '0' COMMENT '本局人数',
  `unit` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT '底分(列表展示用冗余)',
  `rule_json` text COMMENT '开房规则快照(与进房 rule 一致)',
  `init_json` text NOT NULL COMMENT '开局冻结快照(不可变)',
  `ops_json` mediumtext NOT NULL COMMENT '操作流水 JSON 数组 [{"seq","op","seat","fromSeat","tiles","ext"}]',
  `result_json` text COMMENT '结算快照(局末写入)',
  `status` tinyint(3) unsigned NOT NULL DEFAULT '0' COMMENT '0录制中 1已完成可回放 2废弃(解散/流局未完)',
  `op_count` int(10) unsigned NOT NULL DEFAULT '0' COMMENT 'ops 条数(冗余，便于校验)',
  `start_time` datetime DEFAULT NULL COMMENT '本局开始',
  `end_time` datetime DEFAULT NULL COMMENT '本局结束',
  `create_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_round_id` (`round_id`),
  KEY `idx_room_id` (`room_id`),
  KEY `idx_room_num` (`room_num`),
  KEY `idx_game_type_end` (`game_type`,`end_time`),
  KEY `idx_status_end` (`status`,`end_time`)
) ENGINE=InnoDB AUTO_INCREMENT=298 DEFAULT CHARSET=utf8mb4 COMMENT='对局录像主表(全玩法)';

-- ----------------------------
-- Records of h_game_record
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for h_game_record_player
-- ----------------------------
DROP TABLE IF EXISTS `h_game_record_player`;
CREATE TABLE `h_game_record_player` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `record_id` bigint(20) unsigned NOT NULL COMMENT 'h_game_record.id',
  `game_type` tinyint(3) unsigned NOT NULL DEFAULT '0' COMMENT '冗余玩法，列表筛选',
  `room_num` varchar(32) NOT NULL DEFAULT '' COMMENT '冗余房间号',
  `member_id` int(10) unsigned NOT NULL COMMENT '玩家ID',
  `seat_no` tinyint(3) unsigned NOT NULL DEFAULT '0' COMMENT '座位号(与局内一致)',
  `nickname` varchar(64) NOT NULL DEFAULT '',
  `avatar` varchar(255) NOT NULL DEFAULT '',
  `score` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT '本局得分(结算后回填)',
  `is_winner` tinyint(3) unsigned NOT NULL DEFAULT '0' COMMENT '是否赢家侧',
  `is_banker` tinyint(3) unsigned NOT NULL DEFAULT '0' COMMENT '是否庄/地主',
  `create_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_record_member` (`record_id`,`member_id`),
  KEY `idx_member_create` (`member_id`,`create_at`),
  KEY `idx_member_game` (`member_id`,`game_type`,`create_at`)
) ENGINE=InnoDB AUTO_INCREMENT=816 DEFAULT CHARSET=utf8mb4 COMMENT='录像参与者(大厅列表)';

-- ----------------------------
-- Records of h_game_record_player
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for h_game_round
-- ----------------------------
DROP TABLE IF EXISTS `h_game_round`;
CREATE TABLE `h_game_round` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT '局ID',
  `room_id` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '关联房间ID',
  `master_id` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '庄家id',
  `first_bid_seat` tinyint(3) unsigned NOT NULL DEFAULT '0' COMMENT '随机首叫座位',
  `multiple` int(11) unsigned NOT NULL DEFAULT '1' COMMENT '本局最终倍数',
  `extra` text COMMENT '局内扩展状态(JSON)/兼容旧底牌CSV',
  `winner_type` tinyint(1) unsigned NOT NULL DEFAULT '1' COMMENT '赢家类型 1-庄家，2-贤家',
  `winner_user_ids` varchar(255) NOT NULL DEFAULT '' COMMENT '赢家用户ID（多个用逗号分隔）',
  `start_time` datetime DEFAULT NULL COMMENT '该局开始时间',
  `end_time` datetime DEFAULT NULL COMMENT '该局结束时间',
  `create_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `player_ids` varchar(255) NOT NULL DEFAULT '' COMMENT '房间用户id',
  `status` tinyint(1) unsigned NOT NULL DEFAULT '0' COMMENT '0：未开始，1：游戏中，2：游戏结束',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_room_id` (`room_id`) USING BTREE COMMENT '房间ID索引'
) ENGINE=InnoDB AUTO_INCREMENT=530 DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='游戏局记录表';

-- ----------------------------
-- Records of h_game_round
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for h_land_lord_bid
-- ----------------------------
DROP TABLE IF EXISTS `h_land_lord_bid`;
CREATE TABLE `h_land_lord_bid` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `game_round_id` int(11) unsigned NOT NULL COMMENT '关联游戏局ID',
  `seq` tinyint(3) unsigned NOT NULL DEFAULT '0' COMMENT '叫抢顺序(从0递增)',
  `seat_no` tinyint(3) unsigned NOT NULL COMMENT '座位号',
  `member_id` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '玩家ID',
  `action` tinyint(1) unsigned NOT NULL DEFAULT '0' COMMENT '0-不叫/不抢 1-叫地主 2-抢地主',
  `score` smallint(5) unsigned NOT NULL DEFAULT '0' COMMENT '叫分(>0即叫/抢)',
  `multiple` int(11) unsigned NOT NULL DEFAULT '1' COMMENT '此刻累计倍数',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_round_seq` (`game_round_id`,`seq`) USING BTREE COMMENT '防并发重复插入同一步',
  KEY `idx_round` (`game_round_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=769 DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='叫抢地主记录表';

-- ----------------------------
-- Records of h_land_lord_bid
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for h_letter
-- ----------------------------
DROP TABLE IF EXISTS `h_letter`;
CREATE TABLE `h_letter` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `content` text COMMENT '模板内容',
  `read_status` tinyint(1) unsigned NOT NULL DEFAULT '0' COMMENT '0未读1已读',
  `title` varchar(255) NOT NULL DEFAULT '' COMMENT '标题通知',
  `create_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
