  `member_id` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '0：全局',
  `is_del` tinyint(1) unsigned NOT NULL DEFAULT '0' COMMENT '0：未删除，1：删除',
  `thumb` varchar(255) NOT NULL DEFAULT '' COMMENT '图片',
  `type` tinyint(1) unsigned NOT NULL DEFAULT '1' COMMENT '1：系统消息：2业务消息',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_member_del_time` (`member_id`,`is_del`,`create_at`)
) ENGINE=InnoDB AUTO_INCREMENT=157 DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;

