-- ----------------------------
-- Table structure for h_member
-- ----------------------------
DROP TABLE IF EXISTS `h_member`;
CREATE TABLE `h_member` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `email` varchar(255) NOT NULL DEFAULT '' COMMENT '邮箱',
  `passwd` varchar(255) NOT NULL DEFAULT '' COMMENT '密码',
  `register_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '注册时间',
  `login_at` datetime DEFAULT NULL COMMENT '登录时间',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '1：启用；-1：禁用',
  `login_ip` varchar(16) NOT NULL DEFAULT '' COMMENT '登录ip',
  `login_address` varchar(255) NOT NULL DEFAULT '' COMMENT '登录地址',
  `is_agent` tinyint(1) unsigned NOT NULL DEFAULT '0' COMMENT '是否代理1：是，0：否',
  `pid` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '所属父级id',
  `tree` text COMMENT '代理树图',
  `level` tinyint(1) unsigned NOT NULL DEFAULT '1' COMMENT '会员等级',
  `avatar` varchar(255) NOT NULL DEFAULT '' COMMENT '头像',
  `invite_code` varchar(31) NOT NULL DEFAULT '' COMMENT '邀请码',
  `update_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `realname` varchar(31) NOT NULL DEFAULT '' COMMENT '真实姓名',
  `idcard` varchar(63) NOT NULL DEFAULT '' COMMENT '身份证号',
  `audit_status` tinyint(1) unsigned NOT NULL DEFAULT '1' COMMENT '1：未认证，2：认证中，3：认证通过，4：认证失败',
  `trade_passwd` varchar(255) NOT NULL DEFAULT '' COMMENT '支付密码',
  `contract_switch` tinyint(1) unsigned DEFAULT '0' COMMENT '0：不设置 1：盈利，2：亏损',
  `withdraw_status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '1：正常，-1：禁用',
  `customer_link` varchar(255) NOT NULL DEFAULT '' COMMENT '客服链接',
  `points` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT '金币数量',
  `nickname` varchar(255) NOT NULL DEFAULT '' COMMENT '昵称',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=21 DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;

