-- ----------------------------
-- Table structure for h_member_room_card
-- ----------------------------
DROP TABLE IF EXISTS `h_member_room_card`;
CREATE TABLE `h_member_room_card` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `member_id` int(10) unsigned NOT NULL COMMENT '会员 id',
  `type_id` int(10) unsigned NOT NULL COMMENT '房卡类型 id',
  `quantity` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '房卡张数',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_member_type` (`member_id`,`type_id`),
  KEY `idx_type` (`type_id`)
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb4 COMMENT='我的房卡';

-- ----------------------------
-- Records of h_member_room_card
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for h_member_room_card_flow
-- ----------------------------
DROP TABLE IF EXISTS `h_member_room_card_flow`;
CREATE TABLE `h_member_room_card_flow` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `member_id` bigint(20) unsigned NOT NULL,
  `type_id` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '房卡类型 id',
  `change_number` int(11) NOT NULL DEFAULT '0' COMMENT '正数为增加，负数为消耗',
  `after_number` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '变动后房卡余额',
  `flow_type` tinyint(3) unsigned NOT NULL COMMENT '1-购买 2-系统赠送 3-建房消耗 4-返还（解散未满局）',
  `rel_room_id` bigint(20) unsigned DEFAULT NULL COMMENT '关联的房间ID（消耗或返还时）',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `remark` varchar(255) NOT NULL DEFAULT '' COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_player` (`member_id`) USING BTREE,
  KEY `idx_room` (`rel_room_id`) USING BTREE,
  KEY `idx_type` (`type_id`)
) ENGINE=InnoDB AUTO_INCREMENT=80 DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='房卡流水表';

-- ----------------------------
-- Records of h_member_room_card_flow
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for h_menu
-- ----------------------------
DROP TABLE IF EXISTS `h_menu`;
CREATE TABLE `h_menu` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(63) NOT NULL DEFAULT '' COMMENT '菜单名称',
  `group` varchar(63) NOT NULL DEFAULT '' COMMENT '分组',
  `is_menu` tinyint(1) unsigned NOT NULL DEFAULT '0' COMMENT '是否菜单',
  `pid` int(11) NOT NULL DEFAULT '0' COMMENT '父id',
  `icon` varchar(63) NOT NULL DEFAULT '' COMMENT 'icon地址',
  `url` varchar(255) NOT NULL DEFAULT '' COMMENT '菜单地址',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '是否启用1：是-1：否',
  `sort` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '排序',
  `delete_time` datetime DEFAULT NULL,
  `level` tinyint(1) NOT NULL DEFAULT '1' COMMENT '层级',
  `create_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  `create_operator` varchar(63) NOT NULL DEFAULT '' COMMENT '创建人账户',
  `update_operator` varchar(63) NOT NULL DEFAULT '' COMMENT '更新人账号',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=92 DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;

-- ----------------------------
-- Records of h_menu
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for h_niu_bet
-- ----------------------------
DROP TABLE IF EXISTS `h_niu_bet`;
CREATE TABLE `h_niu_bet` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `game_round_id` int(11) unsigned NOT NULL COMMENT '关联游戏局ID',
  `seat_no` tinyint(3) unsigned NOT NULL COMMENT '座位号 0~9',
  `member_id` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '玩家ID',
  `multiple` tinyint(3) unsigned NOT NULL DEFAULT '1' COMMENT '下注倍数（相对底分）',
  `amount` decimal(12,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '实际下注额=底分×倍数',
  `is_auto` tinyint(1) unsigned NOT NULL DEFAULT '0' COMMENT '0手动 1超时默认最小注',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_round_member` (`game_round_id`,`member_id`) USING BTREE,
  KEY `idx_game_round_id` (`game_round_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='斗牛闲家下注记录';

-- ----------------------------
-- Records of h_niu_bet
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for h_niu_grab
-- ----------------------------
DROP TABLE IF EXISTS `h_niu_grab`;
CREATE TABLE `h_niu_grab` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `game_round_id` int(11) unsigned NOT NULL COMMENT '关联游戏局ID',
  `seat_no` tinyint(3) unsigned NOT NULL COMMENT '座位号 0~9',
  `member_id` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '玩家ID',
  `multiple` tinyint(3) unsigned NOT NULL DEFAULT '0' COMMENT '抢庄倍数：0不抢，1~4抢',
  `source` tinyint(1) unsigned NOT NULL DEFAULT '1' COMMENT '1主动抢 2系统明庄',
  `is_auto` tinyint(1) unsigned NOT NULL DEFAULT '0' COMMENT '0手动 1超时默认不抢',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_round_member` (`game_round_id`,`member_id`) USING BTREE,
  KEY `idx_game_round_id` (`game_round_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=282 DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='斗牛抢庄记录';

-- ----------------------------
-- Records of h_niu_grab
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for h_role
-- ----------------------------
DROP TABLE IF EXISTS `h_role`;
CREATE TABLE `h_role` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT '角色id',
  `name` varchar(63) NOT NULL COMMENT '角色名称',
  `privileges` text COMMENT '对应菜单id',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '1：启用：-1禁用',
  `desc` varchar(255) NOT NULL DEFAULT '' COMMENT '描述',
  `update_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  `create_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `create_operator` varchar(63) NOT NULL DEFAULT '' COMMENT '创建人账户',
  `update_operator` varchar(63) NOT NULL DEFAULT '' COMMENT '修改人账户',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;

-- ----------------------------
-- Records of h_role
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for h_room
-- ----------------------------
DROP TABLE IF EXISTS `h_room`;
CREATE TABLE `h_room` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '房间ID',
  `total_play_count` int(11) NOT NULL COMMENT '该房间可玩总局数（由房卡类型决定）',
  `played_count` int(11) NOT NULL DEFAULT '0' COMMENT '已玩局数',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '房间状态 1-已经创建 2-游戏中 3-已结束',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `end_time` datetime DEFAULT NULL COMMENT '房间结束时间',
  `room_num` varchar(31) NOT NULL DEFAULT '' COMMENT '房间号',
  `start_time` datetime DEFAULT NULL COMMENT '开始时间',
  `game_type` tinyint(1) unsigned NOT NULL DEFAULT '1' COMMENT '游戏类型 1斗地主 2斗牛',
  `member_id` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '房主id',
  `num` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '房间人数',
  `rule` text COMMENT '房间规则',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_status` (`status`) USING BTREE COMMENT '房间状态索引'
) ENGINE=InnoDB AUTO_INCREMENT=374 DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='房间表';

-- ----------------------------
-- Records of h_room
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for h_room_card_type
-- ----------------------------
DROP TABLE IF EXISTS `h_room_card_type`;
CREATE TABLE `h_room_card_type` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT COMMENT '类型 id',
  `name` varchar(64) NOT NULL DEFAULT '' COMMENT '房卡名称',
  `price` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT '单张价格（金币）',
  `round_count` int(10) unsigned NOT NULL COMMENT '对应局数',
  `status` tinyint(4) NOT NULL DEFAULT '1' COMMENT '1启用 -1下架',
  `sort` int(11) NOT NULL DEFAULT '0' COMMENT '排序，越大越靠前',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_status_sort` (`status`,`sort`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COMMENT='房卡类型';

-- ----------------------------
-- Records of h_room_card_type
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for h_room_member
-- ----------------------------
DROP TABLE IF EXISTS `h_room_member`;
CREATE TABLE `h_room_member` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `room_id` int(11) unsigned NOT NULL DEFAULT '0',
  `player_id` int(11) unsigned NOT NULL DEFAULT '0',
  `seat_no` tinyint(3) unsigned NOT NULL DEFAULT '0' COMMENT '座位号',
  `join_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `exit_time` datetime DEFAULT NULL,
  `fd` int(11) unsigned NOT NULL DEFAULT '0',
  `is_auto` tinyint(1) unsigned NOT NULL DEFAULT '0' COMMENT '是否自动托管',
  `time_out_num` tinyint(1) unsigned NOT NULL DEFAULT '0' COMMENT '超时三次托管',
  `status` tinyint(1) unsigned NOT NULL DEFAULT '0' COMMENT '0：游戏未开始1：游戏中，2游戏结束',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_room_player` (`room_id`,`player_id`) USING BTREE,
  KEY `idx_player` (`player_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=943 DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='房间成员表';

-- ----------------------------
-- Records of h_room_member
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for h_send_log
-- ----------------------------
DROP TABLE IF EXISTS `h_send_log`;
CREATE TABLE `h_send_log` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `content` text COMMENT '内容',
  `from` varchar(255) NOT NULL DEFAULT '' COMMENT '邮箱或电话号码',
  `mask` varchar(31) NOT NULL DEFAULT '' COMMENT '标识',
  `user_agent` varchar(255) NOT NULL DEFAULT '' COMMENT '客户端',
  `ip` varchar(31) NOT NULL COMMENT '发送ip',
  `create_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `address` varchar(255) NOT NULL DEFAULT '' COMMENT '发送地址',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;

-- ----------------------------
-- Records of h_send_log
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for h_setting
-- ----------------------------
DROP TABLE IF EXISTS `h_setting`;
CREATE TABLE `h_setting` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT COMMENT '配置ID',
  `name` varchar(30) NOT NULL DEFAULT '' COMMENT '配置名称',
  `type` tinyint(3) unsigned NOT NULL DEFAULT '0' COMMENT '配置类型',
  `title` varchar(50) NOT NULL DEFAULT '' COMMENT '配置说明',
  `group` tinyint(3) unsigned NOT NULL DEFAULT '0' COMMENT '配置分组',
  `extra` varchar(255) NOT NULL DEFAULT '' COMMENT '配置值',
  `remark` varchar(100) NOT NULL DEFAULT '' COMMENT '配置说明',
  `create_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `status` tinyint(4) NOT NULL DEFAULT '1' COMMENT '状态1：启用-1：禁用',
  `value` text COMMENT '配置值',
  `sort` smallint(3) unsigned NOT NULL DEFAULT '0' COMMENT '排序',
  `create_uid` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '创建人id',
  `create_operator` varchar(31) NOT NULL DEFAULT '' COMMENT '创建人账号',
  `update_operator` varchar(31) NOT NULL DEFAULT '' COMMENT '更新人账户',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_name` (`name`) USING BTREE,
  KEY `type` (`type`) USING BTREE,
  KEY `group` (`group`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=45 DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC;

-- ----------------------------
-- Records of h_setting
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for h_template
-- ----------------------------
DROP TABLE IF EXISTS `h_template`;
CREATE TABLE `h_template` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `email_content` text COMMENT '模板内容',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态1：上架：-1下架',
  `title` varchar(255) NOT NULL DEFAULT '' COMMENT '标题通知',
  `create_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_operator` varchar(31) NOT NULL DEFAULT '' COMMENT '创建人账号',
  `update_operator` varchar(31) NOT NULL DEFAULT '' COMMENT '更新人账号',
  `mark` varchar(255) NOT NULL DEFAULT '' COMMENT '标识',
  `name` varchar(255) NOT NULL DEFAULT '' COMMENT '模板名称',
  `sort` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '排序',
  `sms_content` varchar(255) NOT NULL DEFAULT '' COMMENT '短息内容',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=34 DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;

-- ----------------------------
-- Records of h_template
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for h_template_content
-- ----------------------------
DROP TABLE IF EXISTS `h_template_content`;
CREATE TABLE `h_template_content` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `template_id` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '模板id',
  `create_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `email` varchar(255) NOT NULL DEFAULT '' COMMENT '邮件地址',
  `content` text COMMENT '内容',
  `ip` varchar(31) NOT NULL DEFAULT '' COMMENT '所属ip',
  `user_agent` varchar(255) NOT NULL DEFAULT '' COMMENT '所属客户端',
  `city` varchar(255) NOT NULL DEFAULT '' COMMENT '所属城市',
  `is_success` tinyint(1) NOT NULL DEFAULT '0' COMMENT '1：发送成功，-1：失败',
  `fail_reason` text COMMENT '失败原因',
  `subject` varchar(255) NOT NULL DEFAULT '' COMMENT '主题',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=52 DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;

-- ----------------------------
-- Records of h_template_content
-- ----------------------------
BEGIN;
COMMIT;

