-- ----------------------------
-- Table structure for h_withdraw
-- ----------------------------
DROP TABLE IF EXISTS `h_withdraw`;
CREATE TABLE `h_withdraw` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `num` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '提现数量',
  `receive_num` decimal(10,2) NOT NULL COMMENT '实际到账金额',
  `fee` decimal(8,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '手续费',
  `member_id` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '会员id',
  `create_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '1：审核中，2：通过，-1拒绝',
  `remark` varchar(255) NOT NULL DEFAULT '' COMMENT '备份',
  `update_operator` varchar(63) NOT NULL DEFAULT '' COMMENT '更新人',
  `address_id` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '提现地址id',
  `order_sn` varchar(255) NOT NULL DEFAULT '' COMMENT '提现单号',
  `channel` varchar(20) NOT NULL DEFAULT '' COMMENT 'wechat/alipay',
  `real_name` varchar(31) NOT NULL DEFAULT '' COMMENT '收款人姓名',
  `pay_account` varchar(64) NOT NULL DEFAULT '' COMMENT '收款账号',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;

-- ----------------------------
-- Records of h_withdraw
-- ----------------------------
BEGIN;
COMMIT;

